const now='2026-09-12T12:00:00Z';const first:WorkspaceExperienceContext={version:1,id:'experience:evening',revision:1,title:'An evening at home',intention:'An ordinary evening, with room for us.',state:'dreaming',horizon:'tonight'};
let context=first,scope={identity:'synthetic-person',environment:'development' as const,householdId:'HH-proof',memberId:'MEM-001'},snapshot:WorkspaceSnapshot={version:1,sequence:1,executionEnabled:false,projects:[]},posts:unknown[]=[],mode:'compact'|'room'|'hidden'='room',lostPublication=false,lostWithdrawal=false,returnCount=0;
let privateReport=false,reportRequest:{id:string;context:FeedbackContext;text?:string}|null=null;
